    def make(n, shape):
        # returns (level order string, list of values)
        vals = rng.sample(range(0, 100001), n)
        left = [-1] * n
        right = [-1] * n
        if shape == 'random':
            free = [(0, 0), (0, 1)]
            for i in range(1, n):
                j = rng.randrange(len(free))
                free[j], free[-1] = free[-1], free[j]
                p, side = free.pop()
                if side == 0:
                    left[p] = i
                else:
                    right[p] = i
                free.append((i, 0))
                free.append((i, 1))
        elif shape == 'left':
            for i in range(1, n):
                left[i - 1] = i
        elif shape == 'zigzag':
            for i in range(1, n):
                if i % 2:
                    left[i - 1] = i
                else:
                    right[i - 1] = i
        else:  # complete
            for i in range(1, n):
                p = (i - 1) // 2
                if i % 2:
                    left[p] = i
                else:
                    right[p] = i
